$(document).ready(function() {
    var bookmark = "{{bookmark}}";

    if (bookmark  == "True") {
      $('[name="addToLibrary"]').addClass("hidden");
      $('[name="removeFromLibrary"]').removeClass("hidden");
    }
    else {
      $('[name="removeFromLibrary"]').addClass("hidden");
      $('[name="addToLibrary"]').removeClass("hidden");
    }

  $('[name="addToLibrary"]').click(function (e) {
    e.preventDefault();
    $.ajax({
      type: "GET",
      url: "/book/bookmark/{{ book.slug }}",
      success: function (result) {
        $('[name="addToLibrary"]').addClass("hidden");
        $('[name="removeFromLibrary"]').removeClass("hidden");
      },
      error: function (result) {
      }
    });
  });

  $('[name="removeFromLibrary"]').click(function (e) {
    e.preventDefault();
    $.ajax({
      type: "GET",
      url: "/book/bookmark/{{ book.slug }}",
      success: function (result) {
        $('[name="removeFromLibrary"]').addClass("hidden");
        $('[name="addToLibrary"]').removeClass("hidden");
      },
      error: function (result) {
      }
    });
  });
});